import Foundation
import ImpactGeometry

// General body geometry (outline model, approved by Joseph 2026-11-24, Google Doc section 28).
//
// An outline body is described by its outer boundary and any holes, in metres in the body's own frame.
// The mesh is generated by ImpactGeometry's quality mesher (Ruppert/Shewchuk Delaunay refinement); the solver
// receives ordinary triangles and never knows how they were made. Bodies with the legacy shapes (block,
// enclosure, round body) keep their structured meshes exactly, so earlier scenes replay bit for bit.

public struct BodyOutline: Codable, Equatable, Sendable {
    /// Outer boundary, any orientation, first point not repeated.
    public var outer: [Point]
    /// Holes strictly inside the outer boundary, disjoint, not nested.
    public var holes: [[Point]]
    /// Target triangle edge length in metres. nil follows the assembly mesh (12 mm ÷ n on the ×n mesh).
    public var meshSize: Double?

    public init(outer: [Point], holes: [[Point]] = [], meshSize: Double? = nil) {
        self.outer = outer
        self.holes = holes
        self.meshSize = meshSize
    }

    public init(_ region: PolygonRegion, meshSize: Double? = nil) {
        self.init(outer: region.outer, holes: region.holes, meshSize: meshSize)
    }

    public var region: PolygonRegion { PolygonRegion(outer: outer, holes: holes) }

    public var bounds: (min: Point, max: Point) { region.bounds }

    /// Allowed explicit edge lengths. Not physics: below 0.05 mm the mesh of an ordinary body would hold
    /// millions of triangles; above 1 m it is coarser than any body the editor makes.
    public static let meshSizeRange = 0.00005...1.0

    /// Edge length that matches the cost of the legacy structured mesh at the same resolution. The legacy
    /// ≈9 mm cell is a square cut into two right triangles whose long edge is ≈12.7 mm; a generated mesh
    /// with 12 mm edges has a similar triangle count and time step (GENERAL_GEOMETRY.md section 9).
    public static let standardEdge = 0.012

    public func edgeLength(resolution: AssemblyScene.Resolution) -> Double {
        meshSize ?? Self.standardEdge / Double(resolution.rawValue)
    }

    /// Every reason the outline cannot be meshed, in plain words.
    public var issues: [String] {
        var result = region.validationIssues()
        if let meshSize, !Self.meshSizeRange.contains(meshSize) {
            result.append(String(format: "mesh size %g mm is outside 0.05 to 1000 mm.", meshSize * 1000))
        }
        return result
    }

    /// The same outline with its bounding box centred on the origin, the shift that was removed, and the
    /// box size. Bodies store outlines this way so `center` is the centre of the box and `size` its extent.
    public func centred() -> (outline: BodyOutline, offset: Point, size: Point) {
        let (low, high) = bounds
        let offset = 0.5 * (low + high)
        var copy = self
        copy.outer = outer.map { $0 - offset }
        copy.holes = holes.map { $0.map { $0 - offset } }
        return (copy, offset, high - low)
    }

    /// The outline stretched so its bounding box is `size` and centred on the origin. Resizing a body by its
    /// width and height fields or the canvas handle scales the outline this way.
    public func fitted(to size: Point) -> BodyOutline {
        let (low, high) = bounds
        let centre = 0.5 * (low + high)
        let extent = high - low
        let scale = Point(extent.x > 0 ? size.x / extent.x : 1, extent.y > 0 ? size.y / extent.y : 1)
        var copy = self
        copy.outer = outer.map { ($0 - centre) * scale }
        copy.holes = holes.map { $0.map { ($0 - centre) * scale } }
        return copy
    }
}

extension AssemblyPart {
    /// The body's material region in its own frame, for every shape. Legacy shapes are converted with the same
    /// dimensions (a round body becomes a polygon of `roundSides` sides). Used by Convert to Outline, Cut and Join.
    public func region(roundSides: Int = 48) -> PolygonRegion {
        switch shape {
        case .outline:
            return (outline ?? BodyOutline(outer: Shapes.rectangle(width: size.x, height: size.y))).fitted(to: size).region
        case .round:
            return PolygonRegion(outer: Shapes.ellipse(width: size.x, height: size.y, sides: roundSides))
        case .enclosure:
            return Shapes.enclosure(width: size.x, height: size.y, wall: wall)
        case .block:
            if let notch {
                return Shapes.notchedBlock(width: size.x, height: size.y, centerFraction: notch.centerFraction,
                                           widthFraction: notch.widthFraction, depthFraction: notch.depthFraction)
            }
            return PolygonRegion(outer: Shapes.rectangle(width: size.x, height: size.y))
        }
    }

    /// A new outline body occupying `region`, given in this body's frame. Its bounding box becomes `size`
    /// and `center` moves so the material stays exactly where it was.
    public func reshaped(to region: PolygonRegion, meshSize: Double? = nil) -> AssemblyPart {
        var part = self
        let (outline, offset, size) = BodyOutline(region.normalized(), meshSize: meshSize ?? outline?.meshSize).centred()
        part.shape = .outline
        part.outline = outline
        part.size = size
        let radians = angle * .pi / 180
        part.center = center + Point(cos(radians) * offset.x - sin(radians) * offset.y,
                                     sin(radians) * offset.x + cos(radians) * offset.y)
        part.notch = nil
        part.bondedLayer = nil
        part.fracture = nil
        part.wall = 0.012
        return part
    }

    /// Plain-language reasons an outline body cannot be meshed, or empty.
    public var outlineIssues: [String] {
        guard shape == .outline else { return outline == nil ? [] : ["an outline is given but the shape is not Outline."] }
        guard let outline else { return ["shape Outline needs an outline (outer boundary points)."] }
        let (low, high) = outline.bounds
        if !(high.x - low.x > 0 && high.y - low.y > 0) { return ["the outline has no width or no height."] }
        return outline.issues
    }

    /// Meshes an outline body. The fitted outline is cached, so repeated edits of other bodies do not re-mesh it.
    func outlineMesh(resolution: AssemblyScene.Resolution) throws -> Mesh {
        guard let outline else { throw AssemblyError.outline(name, "it has no outline.") }
        let fitted = outline.fitted(to: size)
        let edge = outline.edgeLength(resolution: resolution)
        let mesh = try OutlineMeshCache.shared.mesh(region: fitted.region, edge: edge, name: name)
        return Mesh(reference: mesh.points,
                    triangles: mesh.triangles.map { ($0.x, $0.y, $0.z) },
                    boundary: mesh.boundaryEdges.map { Edge($0.x, $0.y) })
    }

    /// Mesher quality and advisory notes for an outline body (never blocking).
    public func outlineAdvice(resolution: AssemblyScene.Resolution) -> ResolutionAdvice? {
        guard shape == .outline, let outline, outlineIssues.isEmpty else { return nil }
        return ResolutionAdvice(region: outline.fitted(to: size).region, targetEdgeLength: outline.edgeLength(resolution: resolution))
    }

    /// Quality metrics of the generated mesh, or nil for legacy shapes and invalid outlines.
    public func outlineQuality(resolution: AssemblyScene.Resolution) -> (quality: MeshQuality, notes: [String])? {
        guard shape == .outline, let outline, outlineIssues.isEmpty else { return nil }
        let fitted = outline.fitted(to: size)
        guard let entry = try? OutlineMeshCache.shared.entry(region: fitted.region, edge: outline.edgeLength(resolution: resolution), name: name)
        else { return nil }
        return (MeshQuality(entry.mesh), entry.notes)
    }
}

extension AssemblyScene {
    /// Replaces a body after its geometry changed (outline edit, Cut, Join, Convert) and moves the gauges and
    /// connection anchors attached to it so they keep their positions in the world. Fractional anchors are
    /// limited to the new body's box.
    public mutating func replace(_ old: AssemblyPart, with new: AssemblyPart) {
        guard let index = parts.firstIndex(where: { $0.id == old.id }) else { return }
        parts[index] = new
        func toWorld(_ p: Point, _ part: AssemblyPart) -> Point {
            let r = part.angle * .pi / 180
            return part.center + Point(cos(r) * p.x - sin(r) * p.y, sin(r) * p.x + cos(r) * p.y)
        }
        func toLocal(_ w: Point, _ part: AssemblyPart) -> Point {
            let r = -part.angle * .pi / 180, d = w - part.center
            return Point(cos(r) * d.x - sin(r) * d.y, sin(r) * d.x + cos(r) * d.y)
        }
        func fraction(_ f: Point) -> Point {
            let local = toLocal(toWorld(0.5 * f * old.size, old), new)
            let g = 2 * local / new.size
            return Point(min(1, max(-1, g.x)), min(1, max(-1, g.y)))
        }
        if var gauges {
            for i in gauges.indices where gauges[i].body == old.id {
                if gauges[i].usesBodyFractions == true { gauges[i].location = fraction(gauges[i].location) }
                else { gauges[i].location = toLocal(toWorld(gauges[i].location, old), new) }
            }
            self.gauges = gauges
        }
        for i in connections.indices {
            if connections[i].first == old.id { connections[i].firstAnchor = fraction(connections[i].firstAnchor) }
            if connections[i].second == old.id { connections[i].secondAnchor = fraction(connections[i].secondAnchor) }
        }
    }
}

/// Generated meshes keyed by region and edge length. The mesher is deterministic (same input, same mesh bit
/// for bit, verified in MeshCheck), so a cached mesh is identical to a fresh one.
final class OutlineMeshCache: @unchecked Sendable {
    static let shared = OutlineMeshCache()
    /// Hard ceiling on generated nodes per body, so a mistyped mesh size cannot exhaust memory. A body this
    /// large would take hours per run on this Mac; the run-cost estimate reports far smaller meshes already.
    static let pointBudget = 400_000
    /// Bodies whose estimated triangle count exceeds this are refused before meshing (memory, not physics).
    static let triangleCeiling = 750_000

    struct Entry { let mesh: TriangleMesh; let notes: [String] }
    private struct Key: Hashable { let outer: [Point]; let holes: [[Point]]; let edge: Double }
    private var entries: [Key: Entry] = [:]
    private var order: [Key] = []
    private let lock = NSLock()

    func entry(region: PolygonRegion, edge: Double, name: String) throws -> Entry {
        let key = Key(outer: region.outer, holes: region.holes, edge: edge)
        lock.lock()
        if let cached = entries[key] { lock.unlock(); return cached }
        lock.unlock()
        let expected = 2.31 * region.area / (edge * edge)
        if expected > Double(Self.triangleCeiling) {
            throw AssemblyError.outline(name, String(format: "a %.3g mm mesh size would need about %@ triangles, more than this Mac can hold for one body (%@). Choose a larger mesh size.",
                                                     edge * 1000, Int(expected).formatted(), Self.triangleCeiling.formatted()))
        }
        let result = Mesher.generate(MeshRequest(region: region, targetEdgeLength: edge, pointBudget: Self.pointBudget))
        guard let mesh = result.mesh else {
            throw AssemblyError.outline(name, result.issues.joined(separator: " "))
        }
        let inverted = mesh.triangles.filter { (t: SIMD3<Int>) -> Bool in
            let ab: Point = mesh.points[t.y] - mesh.points[t.x]
            let ac: Point = mesh.points[t.z] - mesh.points[t.x]
            let doubled: Double = ab.x * ac.y - ab.y * ac.x
            return doubled <= 0
        }.count
        if inverted > 0 { throw AssemblyError.outline(name, "the generated mesh has \(inverted) inverted triangles.") }
        let entry = Entry(mesh: mesh, notes: result.notes)
        lock.lock()
        entries[key] = entry
        order.append(key)
        if order.count > 48 { entries[order.removeFirst()] = nil }
        lock.unlock()
        return entry
    }

    func mesh(region: PolygonRegion, edge: Double, name: String) throws -> TriangleMesh {
        try entry(region: region, edge: edge, name: name).mesh
    }
}
